// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值从 config/thresholds.json 读取；文件不存在、读不出来、内容不是 JSON
// 对象，或该仓库没配，都回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := readThresholds(configPath())[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// configPath 返回 config/thresholds.json 的路径：从当前工作目录向上找到
// go.mod 所在的仓库根，再拼出配置路径；找不到时退回相对路径。
func configPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return filepath.Join("config", "thresholds.json")
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "config", "thresholds.json")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Join("config", "thresholds.json")
		}
		dir = parent
	}
}

// readThresholds 读取并解析阈值配置。任何读取或解析失败都返回 nil，
// 调用方据此回退到默认阈值。
func readThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	thresholds := map[string]int{}
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

